mapper.select:
SELECT COUNT(*) > 0
FROM behavior_catalog_metadata metadata
WHERE metadata.behavior_code = #{behaviorCode}
  AND (
    #{courseCode} = 'ALL_DAY_SUMMARY'
    OR EXISTS (
      SELECT 1 FROM course_behavior_config course_config
      WHERE course_config.course_code = #{courseCode}
        AND course_config.behavior_code = metadata.behavior_code
    )
  )
  AND EXISTS (
    SELECT 1 FROM behavior_environment_config environment_config
    WHERE environment_config.environment_code = #{environmentCode}
      AND environment_config.behavior_code = metadata.behavior_code
  )

mapper.sql:
AND (
  #{courseCode} = 'ALL_DAY_SUMMARY'
  OR EXISTS (
    SELECT 1 FROM course_behavior_config selected_course
    WHERE selected_course.course_code = #{courseCode}
      AND selected_course.behavior_code = metadata.behavior_code
  )
)

  AND EXISTS (
    SELECT 1 FROM behavior_environment_config selected_environment
    WHERE selected_environment.environment_code = #{environmentCode}
      AND selected_environment.behavior_code = metadata.behavior_code
  )
